class TlsLimitMacMoveLevel(TextualConvention, Integer32):
    description = 'This textual convention is used to specify the hierarchy in which\n         spoke-SDPs are blocked when a MAC-move limit is exceeded. When a MAC\n         is moving among multiple SAPs or spoke-SDPs, the SAP bind or spoke-SDP\n         bind with the lower level is blocked first. (tertiary is the lowest)'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3))
    namedValues = NamedValues(("primary", 1), ("secondary", 2), ("tertiary", 3))

class TlsLimitMacMove(TextualConvention, Integer32):
    description = "This textual convention is used to specify the behavior when the\n         relearn rate specified by svcTlsMacMoveMaxRate is exceeded.\n\n         A value of 'blockable' specifies that the agent will\n         monitor the MAC relearn rate on a SAP or SDP Bind and\n         it will block it when the relearn rate specified by\n         svcTlsMacMoveMaxRate is exceeded. A value of 'nonBlockable'\n         specifies that the  SAP or SDP Bind will not be blocked,\n         and another blockable SAP or SDP Bind will be blocked\n         instead."
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2))
    namedValues = NamedValues(("blockable", 1), ("nonBlockable", 2))

class SdpBindVcType(TextualConvention, Integer32):
    description = "This textual convention is used to specify the type of virtual circuit\n         (VC) associated with the SDP binding. The value 'vpls' is no longer\n         supported."
