class StpExceptionCondition(TextualConvention, Integer32):
    description = 'This textual convention is used to specify an STP exception condition\n         encountered on an interface\n         - none : no exception condition found.\n         - oneWayCommuniation : The neighbor RSTP peer on this link\n                                is not able to detect our presence.\n         - downstreamLoopDetected : A loop is detected on this\n           link.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3))
    namedValues = NamedValues(("none", 1), ("oneWayCommuniation", 2), ("downstreamLoopDetected", 3))

class LspIdList(TextualConvention, OctetString):
    description = 'Each group of four octets in this string specify a 32-bit LSP ID,\n         which corresponds to the vRtrMplsLspIndex of the given MPLS LSP. The\n         LSP IDs are stored in network byte order; i.e. octet N corresponds to\n         the most significant 8 bits of the LSP ID, and octet N+3 correspond to\n         the least significant 8 bits. The list is terminated by the null LSP\n         ID. The LSP IDs in this list are not required to be sorted in any\n         specific order. The list is large enough to hold up to 16 LSP IDs,\n         plus the null terminator.'
    status = 'current'
    subtypeSpec = OctetString.subtypeSpec + ValueSizeConstraint(0, 68)

class BridgeId(TextualConvention, OctetString):
    description = 'The Bridge-Identifier used by the Spanning Tree Protocol to uniquely\n         identify a bridge. The first two octets represent the bridge priority\n         (in big endian format) while the remaining six octets represent the\n         main MAC address of the bridge.'
    status = 'current'
    subtypeSpec = OctetString.subtypeSpec + ValueSizeConstraint(8, 8)
    fixedLength = 8

